function draw() {
    ctx.clearRect(0, 0, width, height);
    // ship
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    ctx.beginPath();
    ctx.moveTo(15, 0);
    ctx.lineTo(-10, -8);
    ctx.lineTo(-10, 8);
    ctx.closePath();
    ctx.fillStyle = 'white';
    ctx.fill();
    ctx.restore();
    // fuel bar
    ctx.fillStyle = 'orange';
    ctx.fillRect(10, 10, ship.fuel, 5);
    // bullets
    ctx.fillStyle = 'yellow';
    bullets.forEach(b => ctx.fillRect(b.x - 2, b.y - 2, 4, 4));
    // asteroids
    ctx.strokeStyle = 'gray';
    asteroids.forEach(a => { ctx.beginPath(); ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2); ctx.stroke(); });
    // fuels
    ctx.fillStyle = 'lime';
    fuels.forEach(f => ctx.beginPath(), ctx.arc(f.x, f.y, f.r, 0, Math.PI * 2), ctx.fill());
    // time
    const elapsed = ((performance.now() - startTime) / 1000).toFixed(1);
    ctx.fillStyle = 'white';
    ctx.fillText(`Time: ${elapsed}s`, width - 100, 20);
    if (gameOver) {
      ctx.fillStyle = 'red';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', width / 2 - 60, height / 2);
    }
  }

