function draw() {
    // starfield background
    ctx.fillStyle = 'black';
    ctx.fillRect(0, 0, width, height);
    ctx.fillStyle = 'white';
    stars.forEach(s => {
      ctx.beginPath();
      ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
      ctx.fill();
    });
    // ship with thrust flame
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.rotate(ship.angle);
    // thrust flame when accelerating
    if (keys['ArrowUp'] && ship.fuel > 0) {
      ctx.beginPath();
      ctx.moveTo(-12, 0);
      ctx.lineTo(-22, -5);
      ctx.lineTo(-22, 5);
      ctx.closePath();
      ctx.fillStyle = 'orange';
      ctx.fill();
    }
    ctx.beginPath();
    ctx.moveTo(15, 0);
    ctx.lineTo(-10, -8);
    ctx.lineTo(-10, 8);
    ctx.closePath();
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 1;
    ctx.fill();
    ctx.stroke();
    ctx.restore();
    // fuel bar with gradient
    const fuelGrad = ctx.createLinearGradient(10, 10, 110, 10);
    fuelGrad.addColorStop(0, 'red');
    fuelGrad.addColorStop(1, 'lime');
    ctx.fillStyle = fuelGrad;
    ctx.fillRect(10, 10, ship.fuel, 5);
    // bullets with glow
    ctx.fillStyle = 'yellow';
    ctx.shadowColor = 'yellow';
    ctx.shadowBlur = 8;
    bullets.forEach(b => ctx.beginPath(), ctx.arc(b.x, b.y, 3, 0, Math.PI * 2), ctx.fill());
    ctx.shadowBlur = 0;
    // asteroids with gradient fill
    asteroids.forEach(a => {
      const grad = ctx.createRadialGradient(a.x, a.y, a.r * 0.2, a.x, a.y, a.r);
      grad.addColorStop(0, '#777');
      grad.addColorStop(1, '#222');
      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
      ctx.strokeStyle = '#555';
      ctx.stroke();
    });
    // fuel pickups with glow
    fuels.forEach(f => {
      ctx.save();
      ctx.shadowColor = 'lime';
      ctx.shadowBlur = 6;
      ctx.fillStyle = 'lime';
      ctx.beginPath();
      ctx.arc(f.x, f.y, f.r, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    });
    // time display
    const elapsed = ((performance.now() - startTime) / 1000).toFixed(1);
    ctx.fillStyle = 'white';
    ctx.shadowColor = 'black';
    ctx.shadowBlur = 4;
    ctx.fillText(`Time: ${elapsed}s`, width - 100, 20);
    ctx.shadowBlur = 0;
    if (gameOver) {
      ctx.fillStyle = 'red';
      ctx.font = '24px sans-serif';
      ctx.fillText('Game Over', width / 2 - 60, height / 2);
    }
  }

